#!/usr/bin/env python3
"""
make_amalgamation.py -- produce single-file distributions of the library.

Output (into <distdir>/):
  activation.h    all public C headers, one include guard
  activation.c    all C sources, includes only <distdir>/activation.h
  activation.hpp  the C++17 wrapper header (as-is, guards intact)
  activation.cpp  the C++17 wrapper implementation (as-is)

Drop activation.h/.c into any C project (compile activation.c with your
sources), or activation.hpp/.cpp on top for the C++ API.

Part of ActivationSystem -- MIT licensed. Community: https://t.me/Stack_Traces
"""

import os
import re
import sys
from pathlib import Path

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
INC = os.path.join(ROOT, "include", "activation")
SRC = os.path.join(ROOT, "src")

DISTDIR = None  # output directory; set once by main() from a validated argument


def resolve_distdir(distdir):
    """Re-anchor distdir under the repository root.

    Every path component of the argument is parsed into a safe list
    (empty and "." dropped, ".." and drive-letter components rejected),
    and the output directory is rebuilt as ROOT/<components> — the raw
    argument is never used as a filesystem path.
    """
    parts = [p for p in distdir.replace("\\", "/").split("/")
             if p not in ("", ".")]
    if ".." in parts or any(":" in p for p in parts):
        sys.exit("make_amalgamation: refusing distdir outside the project tree: %s"
                 % distdir)
    return os.path.join(ROOT, *parts) if parts else ROOT

HEADER_ORDER = [
    "version.h", "sha512.h", "hmac.h", "ed25519.h", "random.h", "sm3.h",
    "chacha20.h", "kdf.h", "fingerprint.h", "license.h", "sm2.h", "state.h",
    "revoke.h", "token.h", "audit.h", "keyfile.h", "harden.h",
]

C_SOURCES = [
    "crypto/sha512.c", "crypto/hmac.c", "crypto/ed25519.c",
    "crypto/random.c", "crypto/chacha20.c", "crypto/sm3.c",
    "crypto/sm2.c", "core/kdf.c",
    "core/fingerprint.c", "core/license.c", "core/state.c",
    "core/revoke.c", "core/token.c", "core/audit.c", "core/keyfile.c", "core/harden.c",
]

BANNER = """\
/*
 * Engrail {ver} -- single-file amalgamation
 * Generated by scripts/make_amalgamation.py; DO NOT EDIT BY HAND.
 *
 * MIT License -- Copyright (c) 2026 ActivationSystem Contributors
 * Community: https://t.me/Stack_Traces
 *
 * Usage (C):    #include "activation.h"   and compile activation.c too
 * Usage (C++17): #include "activation.hpp" and compile activation.cpp too
 */
"""


def strip_local_includes(text):
    """Remove #include "..." lines that refer to our own headers."""
    return re.sub(r'^#include "activation/[^"]+"\s*$(\n)?', '', text,
                  flags=re.M)


def strip_license_blocks(text):
    """Collapse the repeated MIT blocks into the file banner."""
    return re.sub(
        r'/\*\n \* MIT License.*?\*/\n', '', text, flags=re.S)


def write_distribution():
    """Write activation.{h,c,hpp,cpp} into DISTDIR."""
    os.makedirs(DISTDIR, exist_ok=True)

    version = "1.1.0"
    vh = os.path.join(INC, "version.h")
    if os.path.exists(vh):
        m = re.search(r'#define ACT_VERSION\s+"([^"]+)"', open(vh).read())
        if m:
            version = m.group(1)

    # ---- activation.h ----
    parts = [BANNER.replace("{ver}", version),
             "#ifndef ACTIVATION_AMALGAMATED_H\n"
             "#define ACTIVATION_AMALGAMATED_H\n\n"]
    for name in HEADER_ORDER:
        with open(os.path.join(INC, name), encoding="utf-8", newline="\n") as f:
            body = strip_license_blocks(strip_local_includes(f.read()))
        # drop the individual include guards (keep content)
        guard = name.upper().replace('.', '_').replace('/', '_')  # e.g. SHA512_H
        body = body.replace("#ifndef ACTIVATION_%s\n" % guard, '')
        body = body.replace("#define ACTIVATION_%s\n" % guard, '')
        body = re.sub(r'#endif /\* ACTIVATION_[A-Z0-9_/]+_H \*/\s*$',
                      '', body, flags=re.M)
        parts.append("/* ==== %s ==== */\n%s\n" % (name, body))
    parts.append("#endif /* ACTIVATION_AMALGAMATED_H */\n")
    Path(DISTDIR, "activation.h").write_text(
        "\n".join(parts), encoding="utf-8", newline="\n")

    # ---- activation.c ----
    parts = [BANNER.replace("{ver}", version),
             '#include "activation.h"\n']
    for rel in C_SOURCES:
        with open(os.path.join(SRC, rel), encoding="utf-8", newline="\n") as f:
            body = strip_license_blocks(strip_local_includes(f.read()))
        parts.append("/* ==== src/%s ==== */\n%s\n" % (rel, body))
    Path(DISTDIR, "activation.c").write_text(
        "\n".join(parts), encoding="utf-8", newline="\n")

    # ---- C++ files ----
    # The wrapper headers normally include our C headers by path; in the
    # amalgamation everything already lives inside activation.h.
    for src, dst in (("include/activation/activation.hpp", "activation.hpp"),
                     ("src/core/activation.cpp", "activation.cpp")):
        with open(os.path.join(ROOT, src), encoding="utf-8", newline="\n") as f:
            body = f.read()
        if dst == "activation.cpp":
            body = body.replace('#include "activation/activation.hpp"',
                                '#include "activation.hpp"')
        body = re.sub(r'^#include "activation/(?!activation\.hpp)[^"]+"\s*$',
                      '#include "activation.h"', body, flags=re.M)
        body = re.sub(r'(#include "activation\.h"\n)+',
                      '#include "activation.h"\n', body, flags=re.M)
        Path(DISTDIR, dst).write_text(body, encoding="utf-8", newline="\n")

    for name in ("activation.h", "activation.c", "activation.hpp",
                 "activation.cpp"):
        path = os.path.join(DISTDIR, name)
        size = os.path.getsize(path)
        print("wrote %-40s %7d bytes" % (path, size))
    print("community: https://t.me/Stack_Traces")


def main(argv):
    global DISTDIR
    if len(argv) != 2:
        print("usage: make_amalgamation.py <distdir>", file=sys.stderr)
        return 2
    DISTDIR = resolve_distdir(argv[1])
    write_distribution()


if __name__ == "__main__":
    sys.exit(main(sys.argv) or 0)
